-- Grade 7 Question Bank: 200 uniquely authored questions (40 concepts x 5 types).
-- Requires 00_foundation.sql. Run manually on a disposable DB after Flyway V52.
BEGIN;
CREATE TEMP TABLE g7q(bank_name text,unit_code text,type varchar(30),difficulty varchar(20),content text,explanation text,hint text,options jsonb,answers jsonb) ON COMMIT DROP;

-- Add only missing seed-owned questions; natural key is the complete tagged prompt.
SELECT s.type,s.difficulty,s.content,s.explanation,s.hint,TRUE,'CASE_INSENSITIVE_TRIM',1
FROM g7q s
WHERE NOT EXISTS(SELECT 1 FROM questions q WHERE q.content=s.content);

SELECT q.id,qb.id FROM g7q s
JOIN questions q ON q.content=s.content
JOIN content_units u ON u.code=s.unit_code
JOIN content_sections sec ON sec.unit_id=u.id AND sec.name='Vocabulary'
JOIN content_topics t ON t.section_id=sec.id AND t.name='G7-SEED Core Practice'
JOIN content_question_banks qb ON qb.topic_id=t.id AND qb.name='G7-SEED Bank '||s.bank_name
ON CONFLICT(question_id) DO NOTHING;

SELECT q.id,chr(64+opt.ord::integer),opt.obj->>'content',
       (opt.obj->>'isCorrect')::boolean,opt.ord::integer
FROM g7q s JOIN questions q ON q.content=s.content
CROSS JOIN LATERAL jsonb_array_elements(s.options) WITH ORDINALITY opt(obj,ord)
ON CONFLICT(question_id,option_key) DO NOTHING;

SELECT q.id,a.obj->>'rawValue',lower(btrim(a.obj->>'rawValue'))
FROM g7q s JOIN questions q ON q.content=s.content
CROSS JOIN LATERAL jsonb_array_elements(s.answers) a(obj)
WHERE NOT EXISTS (SELECT 1 FROM question_answers qa WHERE qa.question_id=q.id AND qa.raw_value=a.obj->>'rawValue');

DO $check$
DECLARE n integer;
BEGIN
 SELECT count(*) INTO n
 FROM content_questions cq JOIN questions q ON q.id=cq.question_id
 WHERE q.content LIKE '[G7-SEED %';
 IF n <> 200 THEN RAISE EXCEPTION 'Expected 200 Grade 7 seed bank questions, found %',n; END IF;
 IF EXISTS(SELECT 1 FROM content_questions cq JOIN questions q ON q.id=cq.question_id
           WHERE q.content LIKE '[G7-SEED %' AND q.type IN ('MATCHING','CLOZE')) THEN
   RAISE EXCEPTION 'Compound question leaked into a Grade 7 Question Bank';
 END IF;
END $check$;
COMMIT;
